						t.Fatal(err)
					}
					var supersessionCount, exactLineageCount int
					{
						var err error
						supersessionCount, err = channelAnchorStorageObservation(t, h).CountRunNamedEventStorage(context.Background(), fork.ForkRunID, "mailbox.card_superseded")
