					if log.ErrorCode == code {
						if log.RunID != opened.RunID || log.Action != "serve_fan_out_obligation" || log.Failure == nil || log.Failure.Detail.Code != code {
							t.Fatalf("actual served failure lost canonical identity: %+v", log)
