				t.Fatalf("blocked runtime intent lost exact failure/eligibility: %+v", row)
			}
			if incident.Count != 1 || len(incident.SampleLogIDs) != 1 || incident.SampleLogIDs[0] != sampleID || incident.Component != "workflow-runtime" {
