							continue
						}
						for _, route := range event.HistoricalDeliveryRoutes {
							if reflect.DeepEqual(route, want.route) {
								matches++
							}
						}
					}
					for _, event := range history.SelectedRouteEvents {
						if event.SourceEventID != want.eventID {
							continue
						}
						for _, route := range event.HistoricalDeliveryRoutes {
							if reflect.DeepEqual(route, want.route) {
								matches++
							}
						}
					}
					if matches != 1 {
