				t.Fatalf("gate did not commit before crash: %#v", before)
			}
			compiled, ok := before[0].Evidence.Compiled()
			if !ok || compiled.FlowID() != "." || compiled.Edge().Source != "gate" || compiled.Edge().Verdict != "approve" {
